    ja: "\u30b5\u30a4\u30f3\u30a4\u30f3\u3057\u3066\u6700\u521d\u306e\u30b2\u30fc\u30e0\u3092\u4f5c\u308d\u3046", ko: "\ub85c\uadf8\uc778\ud558\uc5ec \uccab \uac8c\uc784\uc744 \ub9cc\ub4dc\uc138\uc694",
